#!/usr/bin/env bash
# Copies the shared platform libraries and the message contracts into each service (ADR-0017).
#
#   shared/go/<pkg>        -> services/<svc>/internal/platform/<pkg>   (import path rewritten)
#   shared/dotnet/src/**.cs -> services/<svc>/src/<Project>/Platform/**
#   contracts/ (relevant)  -> services/<svc>/contracts/                 (by x-producer / x-consumers)
#
# Targets for the libraries live in scripts/sync-shared.conf. Every destination gets a .vendored.json
# with {source, version, sha256}; copied source files get a DO NOT EDIT header.
#
# Usage: scripts/sync-shared.sh [--check] [--root DIR]
#   --check  regenerate in a temp dir and diff against the services; exit 1 listing every divergent path.
set -euo pipefail

check=0
root="$(cd "$(dirname "$0")/.." && pwd)"
while [ $# -gt 0 ]; do
  case "$1" in
    --check) check=1 ;;
    --root) root="$(cd "$2" && pwd)"; shift ;;
    *) echo "usage: $0 [--check] [--root DIR]" >&2; exit 2 ;;
  esac
  shift
done

GO_IMAGE="${GO_IMAGE:-golang:1.25}"
conf="$root/scripts/sync-shared.conf"
work="$(mktemp -d "${TMPDIR:-/tmp}/sync-shared.XXXXXX")"
trap 'rm -rf "${work:?}"' EXIT

sha256_stdin() { if command -v sha256sum >/dev/null 2>&1; then sha256sum | cut -d' ' -f1; else shasum -a 256 | cut -d' ' -f1; fi; }
sha256_file() { sha256_stdin < "$1"; }

# Runs a Go toolchain command in $1 (dir); uses the local toolchain or the official image.
run_go() {
  local dir="$1"; shift
  if command -v go >/dev/null 2>&1; then
    (cd "$dir" && "$@")
  else
    docker run --rm -v "$dir:/src" -w /src -v ticketpro-go-cache:/go/pkg -e GOCACHE=/go/pkg/.build-cache "$GO_IMAGE" "$@"
  fi
}

# Prints source files (relative to $1) for a library, one per line, sorted.
list_go_sources() {
  (cd "$1" && find . -type f -name '*.go' ! -name '*_test.go' \
    ! -path '*/testdata/*' ! -path './internal/*' | sed 's#^\./##' | LC_ALL=C sort)
}
list_dotnet_sources() {
  (cd "$1" && find . -type f -name '*.cs' ! -path '*/bin/*' ! -path '*/obj/*' | sed 's#^\./##' | LC_ALL=C sort)
}

# Fingerprint of the included source files: sha256 over the sorted "hash  path" list.
fingerprint() { # dir, file-list
  local dir="$1" list="$2" f
  while IFS= read -r f; do
    [ -n "$f" ] && printf '%s  %s\n' "$(sha256_file "$dir/$f")" "$f"
  done <<< "$list" | sha256_stdin
}

write_vendored() { # dest-dir, source, version, sha
  printf '{"source":"%s","version":"%s","sha256":"%s"}\n' "$2" "$3" "$4" > "$1/.vendored.json"
}

# ---------- generation into $work/<service-relative path> ----------

gen_go() { # service, module
  local svc="$1" module="$2" src="$root/shared/go" list version out f
  list="$(list_go_sources "$src")"
  [ -n "$list" ] || return 0
  version="$(tr -d '[:space:]' < "$src/VERSION")"
  out="$work/services/$svc/internal/platform"
  mkdir -p "$out"
  while IFS= read -r f; do
    mkdir -p "$out/$(dirname "$f")"
    {
      printf '// Code generated by scripts/sync-shared.sh from shared/go@%s. DO NOT EDIT.\n\n' "$version"
      sed "s#github.com/ticketpro/platform/#$module/internal/platform/#g" "$src/$f"
    } > "$out/$f"
  done <<< "$list"
  # Rewritten import paths can change import ordering; normalize like the service's own lint would.
  run_go "$out" gofmt -w .
  write_vendored "$out" "shared/go" "$version" "$(fingerprint "$src" "$list")"
}

gen_dotnet() { # service, project
  local svc="$1" project="$2" src="$root/shared/dotnet/src" list version out f
  [ -d "$src" ] || return 0
  list="$(list_dotnet_sources "$src")"
  [ -n "$list" ] || return 0
  version="$(tr -d '[:space:]' < "$root/shared/dotnet/VERSION")"
  out="$work/services/$svc/src/$project/Platform"
  mkdir -p "$out"
  while IFS= read -r f; do
    mkdir -p "$out/$(dirname "$f")"
    {
      printf '// <auto-generated>\n'
      printf '// Copied by scripts/sync-shared.sh from shared/dotnet@%s. DO NOT EDIT: change the source and run scripts/sync-shared.sh.\n' "$version"
      printf '// </auto-generated>\n\n'
      cat "$src/$f"
    } > "$out/$f"
  done <<< "$list"
  write_vendored "$out" "shared/dotnet" "$version" "$(fingerprint "$src" "$list")"
}

gen_contracts() {
  local src="$root/contracts" version schemas svc s type list out f
  [ -f "$src/VERSION" ] || return 0
  version="$(tr -d '[:space:]' < "$src/VERSION")"
  schemas="$(cd "$src" && find events -type f -name 'v*.schema.json' | LC_ALL=C sort)"
  for svc in $(cd "$src" && for s in $schemas; do jq -r '[."x-producer"] + (."x-consumers" // []) | .[]' "$s"; done | LC_ALL=C sort -u); do
    if [ ! -d "$root/services/$svc" ]; then
      echo "warning: contracts mention $svc but services/$svc does not exist; skipped" >&2
      continue
    fi
    list="envelope.schema.json
common.schema.json"
    for s in $schemas; do
      if (cd "$src" && jq -e --arg s "$svc" '."x-producer" == $s or ((."x-consumers" // []) | index($s))' "$s" >/dev/null); then
        type="$(basename "$(dirname "$s")")"
        list="$list
$s"
        for f in $(cd "$src" && ls examples/"$type".v*.json 2>/dev/null); do list="$list
$f"; done
      fi
    done
    list="$(printf '%s\n' "$list" | LC_ALL=C sort -u)"
    out="$work/services/$svc/contracts"
    while IFS= read -r f; do
      mkdir -p "$out/$(dirname "$f")"
      cp "$src/$f" "$out/$f"
    done <<< "$list"
    write_vendored "$out" "contracts" "$version" "$(fingerprint "$src" "$list")"
  done
}

if [ -f "$conf" ]; then
  while read -r kind svc target _; do
    case "$kind" in
      ''|'#'*) continue ;;
      go) gen_go "$svc" "$target" ;;
      dotnet) gen_dotnet "$svc" "$target" ;;
      *) echo "unknown kind in $conf: $kind" >&2; exit 2 ;;
    esac
  done < "$conf"
fi
gen_contracts

# ---------- apply or compare ----------
# Destinations owned by this script: every generated tree, plus any existing vendored tree (so a target
# removed from the config or a library with no sources is reported/cleaned too).
dests="$( { (cd "$work" && find services -name .vendored.json); (cd "$root" && find services -name .vendored.json 2>/dev/null); } \
  | xargs -n1 dirname 2>/dev/null | LC_ALL=C sort -u)"

status=0
for d in $dests; do
  mkdir -p "$work/$d"
  if [ "$check" -eq 1 ]; then
    if [ ! -d "$root/$d" ]; then
      echo "missing: $d"; status=1; continue
    fi
    if ! diff -rq "$work/$d" "$root/$d" > "$work/.diff" 2>&1; then
      sed "s#$work/##g; s#$root/##g" "$work/.diff"
      status=1
    fi
  else
    mkdir -p "$root/$d"
    rsync -a --delete "$work/$d/" "$root/$d/"
    # A tree that is now empty except for nothing generated is removed entirely.
    if [ -z "$(ls -A "$root/$d")" ]; then rmdir "$root/$d"; fi
  fi
done

if [ "$check" -eq 1 ]; then
  if [ "$status" -ne 0 ]; then echo "sync-shared --check: vendored copies are out of date; run scripts/sync-shared.sh" >&2; fi
  exit "$status"
fi

# Keep each Go service's go.mod/go.sum in line with what the vendored platform imports.
if [ -f "$conf" ]; then
  while read -r kind svc _; do
    if [ "$kind" = "go" ] && [ -f "$root/services/$svc/go.mod" ] && [ -d "$root/services/$svc/internal/platform" ]; then
      # Pin the library's module versions first, so tidy never picks newer (unvetted) releases.
      requires="$(awk '/^require \(/{b=1;next} b&&/^\)/{b=0} b&&NF>=2{print "-require=" $1 "@" $2} /^require [^(]/{print "-require=" $2 "@" $3}' "$root/shared/go/go.mod")"
      # shellcheck disable=SC2086
      [ -z "$requires" ] || run_go "$root/services/$svc" go mod edit $requires
      run_go "$root/services/$svc" go mod tidy
    fi
  done < "$conf"
fi
echo "sync-shared: done"
